def run(scenario):
    with tempfile.NamedTemporaryFile("w", suffix=".json", delete=False) as f:
        json.dump(scenario, f)
        path = f.name
    out = subprocess.run(["bash", SIM, path], capture_output=True, text=True, timeout=900)
