[[ -f "$DEPLOY_DIR/.admin-v2-deploy-root" ]] || fail "배포 경로 표식이 없습니다. 최초 1회 ADMIN_V2_INIT_DEPLOY_ROOT=true로 실행하십시오."

RSYNC_ARGS=(-r --checksum --itemize-changes --exclude index.html --exclude integrity-manifest.json)
if [[ "$DRY_RUN" == "true" ]]; then
  RSYNC_ARGS+=(-n)
fi

echo "[admin-v2 deploy] changed files: $SOURCE_DIR -> $DEPLOY_DIR"
rsync "${RSYNC_ARGS[@]}" "$SOURCE_DIR/" "$DEPLOY_DIR/"

if [[ "$DRY_RUN" == "true" ]]; then
  for SPECIAL_FILE in integrity-manifest.json index.html; do
    if [[ ! -f "$DEPLOY_DIR/$SPECIAL_FILE" ]] || ! cmp -s -- "$SOURCE_DIR/$SPECIAL_FILE" "$DEPLOY_DIR/$SPECIAL_FILE"; then
      echo ">f.changed.. $SPECIAL_FILE"
    fi
  done
  echo "[admin-v2 deploy] dry-run 완료"
  exit 0
fi

copy_atomically_if_changed() {
  local source_file="$1"
  local target_file="$2"
  local temporary_file="$3"

  if [[ -f "$target_file" ]] && cmp -s -- "$source_file" "$target_file"; then
    echo "[admin-v2 deploy] unchanged: $(basename -- "$target_file")"
    return
  fi

  install -m 0644 "$source_file" "$temporary_file"
  mv -f "$temporary_file" "$target_file"
  echo "[admin-v2 deploy] updated: $(basename -- "$target_file")"
}

copy_atomically_if_changed \
  "$SOURCE_DIR/integrity-manifest.json" \
  "$DEPLOY_DIR/integrity-manifest.json" \
  "$DEPLOY_DIR/.integrity-manifest.json.next"
copy_atomically_if_changed \
  "$SOURCE_DIR/index.html" \
  "$DEPLOY_DIR/index.html" \
  "$DEPLOY_DIR/.index.html.next"

echo "[admin-v2 deploy] 완료: 변경된 파일만 전송했고 index.html은 필요한 경우 마지막에 교체했습니다."

